-- Dosages disponibles et posologies par indication des médicaments per os, extraits du Compendium (fichier AIPS du 10.11.2026).
-- Généré par tools/compendium/aips_rx.py ; les textes créés sont des brouillons invisibles des médecins jusqu'à validation par un admin.
-- À exécuter après sl.sql et sl_rx_indication.sql. Sans danger si relancé (aucun texte existant n'est écrasé, sauf les dosages disponibles).

alter table public.sl_rx add column if not exists strengths jsonb not null default '[]';

-- 1. Dosages disponibles (affichés sous le tableau des paliers)
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "50 mg"}, {"form": "comprimé pelliculé", "dose": "100 mg"}, {"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb where substance = 'abemaciclib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "500 mg"}]'::jsonb where substance = 'abirateron';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "20 mg"}, {"form": "comprimé pelliculé", "dose": "30 mg"}, {"form": "comprimé pelliculé", "dose": "40 mg"}, {"form": "comprimé pelliculé", "dose": "50 mg"}]'::jsonb where substance = 'afatinib';
update public.sl_rx set strengths = '[{"form": "gélule", "dose": "150 mg"}]'::jsonb where substance = 'alectinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "50 mg"}, {"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb where substance = 'alpelisib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "60 mg"}, {"form": "comprimé pelliculé", "dose": "240 mg"}]'::jsonb where substance = 'apalutamid';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "1 mg"}, {"form": "comprimé pelliculé", "dose": "3 mg"}, {"form": "comprimé pelliculé", "dose": "5 mg"}, {"form": "comprimé pelliculé", "dose": "7 mg"}]'::jsonb where substance = 'axitinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "15 mg"}, {"form": "comprimé pelliculé", "dose": "45 mg"}]'::jsonb where substance = 'binimetinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "30 mg"}, {"form": "comprimé pelliculé", "dose": "90 mg"}, {"form": "comprimé pelliculé", "dose": "180 mg"}]'::jsonb where substance = 'brigatinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "20 mg"}, {"form": "comprimé pelliculé", "dose": "40 mg"}, {"form": "comprimé pelliculé", "dose": "60 mg"}]'::jsonb where substance = 'cabozantinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "500 mg"}]'::jsonb where substance = 'capecitabine';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "160 mg"}, {"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb where substance = 'capivasertib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb where substance = 'capmatinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "20 mg"}]'::jsonb where substance = 'cobimetinib';
update public.sl_rx set strengths = '[{"form": "granulé", "dose": "20 mg"}, {"form": "granulé", "dose": "50 mg"}, {"form": "granulé", "dose": "150 mg"}, {"form": "gélule", "dose": "200 mg"}, {"form": "gélule", "dose": "250 mg"}]'::jsonb where substance = 'crizotinib';
update public.sl_rx set strengths = '[{"form": "comprimé dispersible", "dose": "10 mg"}, {"form": "gélule", "dose": "50 mg"}, {"form": "gélule", "dose": "75 mg"}]'::jsonb where substance = 'dabrafenib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "300 mg"}]'::jsonb where substance = 'darolutamid';
update public.sl_rx set strengths = '[{"form": "gélule", "dose": "50 mg"}, {"form": "gélule", "dose": "75 mg"}]'::jsonb where substance = 'encorafenib';
update public.sl_rx set strengths = '[{"form": "gélule", "dose": "100 mg"}, {"form": "gélule", "dose": "200 mg"}]'::jsonb where substance = 'entrectinib';
update public.sl_rx set strengths = '[{"form": "comprimé", "dose": "40 mg"}, {"form": "comprimé", "dose": "80 mg"}]'::jsonb where substance = 'enzalutamid';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "25 mg"}, {"form": "comprimé pelliculé", "dose": "100 mg"}, {"form": "comprimé pelliculé", "dose": "150 mg"}]'::jsonb where substance = 'erlotinib';
update public.sl_rx set strengths = '[{"form": "comprimé", "dose": "2,5 mg"}, {"form": "comprimé", "dose": "5 mg"}, {"form": "comprimé", "dose": "10 mg"}]'::jsonb where substance = 'everolimus';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "250 mg"}]'::jsonb where substance = 'gefitinib';
update public.sl_rx set strengths = '[{"form": "gélule", "dose": "25 mg"}, {"form": "gélule", "dose": "100 mg"}]'::jsonb where substance = 'larotrectinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "80 mg"}, {"form": "comprimé pelliculé", "dose": "240 mg"}]'::jsonb where substance = 'lazertinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "25 mg"}, {"form": "comprimé pelliculé", "dose": "100 mg"}]'::jsonb where substance = 'lorlatinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "40 mg"}]'::jsonb where substance = 'neratinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "100 mg"}, {"form": "comprimé pelliculé", "dose": "150 mg"}]'::jsonb where substance = 'olaparib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "40 mg"}, {"form": "comprimé pelliculé", "dose": "80 mg"}]'::jsonb where substance = 'osimertinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "75 mg"}, {"form": "comprimé pelliculé", "dose": "100 mg"}, {"form": "comprimé pelliculé", "dose": "125 mg"}, {"form": "gélule", "dose": "75 mg"}, {"form": "gélule", "dose": "100 mg"}, {"form": "gélule", "dose": "125 mg"}]'::jsonb where substance = 'palbociclib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "200 mg"}, {"form": "comprimé pelliculé", "dose": "400 mg"}]'::jsonb where substance = 'pazopanib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "40 mg"}]'::jsonb where substance = 'regorafenib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb where substance = 'ribociclib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "40 mg"}, {"form": "comprimé pelliculé", "dose": "80 mg"}, {"form": "gélule", "dose": "40 mg"}, {"form": "gélule", "dose": "80 mg"}]'::jsonb where substance = 'selpercatinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb where substance = 'sorafenib';
update public.sl_rx set strengths = '[{"form": "gélule", "dose": "12,5 mg"}, {"form": "gélule", "dose": "25 mg"}, {"form": "gélule", "dose": "50 mg"}]'::jsonb where substance = 'sunitinib';
update public.sl_rx set strengths = '[{"form": "gélule", "dose": "0,1 mg"}, {"form": "gélule", "dose": "0,25 mg"}, {"form": "gélule", "dose": "0,35 mg"}, {"form": "gélule", "dose": "0,5 mg"}, {"form": "gélule", "dose": "1 mg"}]'::jsonb where substance = 'talazoparib';
update public.sl_rx set strengths = '[{"form": "capsule", "dose": "5 mg"}, {"form": "capsule", "dose": "20 mg"}, {"form": "capsule", "dose": "100 mg"}, {"form": "capsule", "dose": "140 mg"}, {"form": "capsule", "dose": "180 mg"}, {"form": "capsule", "dose": "250 mg"}]'::jsonb where substance = 'temozolomid';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "225 mg"}]'::jsonb where substance = 'tepotinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "0,5 mg"}, {"form": "comprimé pelliculé", "dose": "2 mg"}, {"form": "poudre", "dose": "4,7 mg"}]'::jsonb where substance = 'trametinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "15 mg/6,14 mg"}, {"form": "comprimé pelliculé", "dose": "20 mg/8,19 mg"}]'::jsonb where substance = 'trifluridin';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "50 mg"}, {"form": "comprimé pelliculé", "dose": "150 mg"}]'::jsonb where substance = 'tucatinib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "240 mg"}]'::jsonb where substance = 'vemurafenib';
update public.sl_rx set strengths = '[{"form": "comprimé pelliculé", "dose": "10 mg"}, {"form": "comprimé pelliculé", "dose": "40 mg"}]'::jsonb where substance = 'vorasidenib';

-- 2. Indication ajoutée aux brouillons existants dont la posologie correspond à une indication du RCP
update public.sl_rx set indication = 'Hormonothérapie', indication_match = null where substance = 'abemaciclib' and product_line = 'abémaciclib, comprimé 150 mg' and indication is null and status = 'draft';
update public.sl_rx set indication = 'Monothérapie', indication_match = null where substance = 'cabozantinib' and product_line = 'cabozantinib, comprimé 60 mg' and indication is null and status = 'draft';
update public.sl_rx set indication = 'Cancer du sein avancé ou métastatique', indication_match = 'sein;mammaire;avance;metastatique' where substance = 'ribociclib' and product_line = 'ribociclib, comprimé 200 mg' and indication is null and status = 'draft';
update public.sl_rx set indication = 'GIST et RCC', indication_match = 'stromal;gist;renal;cellules renales' where substance = 'sunitinib' and product_line = 'sunitinib, capsule 50 mg' and indication is null and status = 'draft';
update public.sl_rx set indication = 'Monothérapie (cancer du sein)', indication_match = 'sein;mammaire' where substance = 'talazoparib' and product_line = 'talazoparib, capsule 1 mg' and indication is null and status = 'draft';

-- 3. Nouvelles posologies par indication ou forme galénique (brouillons)
insert into public.sl_rx (substance, product_line, indication, indication_match, sig, dose_levels, dose_note, source, status, position, strengths)
select v.* from (values
  ('abemaciclib', 'abémaciclib, comprimé 200 mg', 'Monothérapie', null, 'S. 200 mg = 1 cp à prendre 2 fois par jour', '[["Dose initiale", "200 mg 2x/j"]]'::jsonb, 'La dose recommandée d''abémaciclib est de 200 mg deux fois par jour.', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Verzenios®', 'draft', 100, '[{"form": "comprimé pelliculé", "dose": "50 mg"}, {"form": "comprimé pelliculé", "dose": "100 mg"}, {"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb),
  ('cabozantinib', 'cabozantinib, comprimé 40 mg', 'En association avec le nivolumab dans le RCC avancé en première ligne', 'renal;cellules renales;avance;metastatique;nivolumab', 'S. 40 mg = 1 cp à prendre une fois par jour', '[["Dose initiale", "40 mg 1x/j"]]'::jsonb, 'La dose recommandée de CABOMETYX est de 40 mg une fois par jour, par voie orale, en association avec 240 mg de nivolumab, administré en perfusion intraveineuse toutes les 2 semaines.', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : CABOMETYX® 20 mg, 40 mg, 60 mg comprimés pelliculés', 'draft', 101, '[{"form": "comprimé pelliculé", "dose": "20 mg"}, {"form": "comprimé pelliculé", "dose": "40 mg"}, {"form": "comprimé pelliculé", "dose": "60 mg"}]'::jsonb),
  ('capecitabine', 'capécitabine, comprimé 500 mg', 'Monothérapie (6 mois) ; Monothérapie ; En combinaison avec le docétaxel', 'docetaxel', 'S. 1250 mg/m² 2 fois par jour [dose en mg à calculer selon la surface corporelle]', '[["Dose initiale", "1250 mg/m² 2x/j"]]'::jsonb, 'La posologie recommandée de Xeloda en monothérapie est de 1250 mg/m² deux fois par jour (matin et soir, ce qui correspond à une dose journalière totale de 2500 mg/m²) pendant 14 jours, période à laquelle succède une fenêtre thérapeutique de sept jours.', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Xeloda®', 'draft', 102, '[{"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "500 mg"}]'::jsonb),
  ('capecitabine', 'capécitabine, comprimé 500 mg', 'En combinaison avec l’oxaliplatine ; En combinaison avec la vinorelbine', 'oxaliplatine;vinorelbine', 'S. 1000 mg/m² 2 fois par jour [dose en mg à calculer selon la surface corporelle]', '[["Dose initiale", "1000 mg/m² 2x/j"]]'::jsonb, 'Après l’ oxaliplatine , administré sous forme de perfusion intraveineuse à la dose de 130 mg/m² sur 2 heures, en commençant le même jour avec Xeloda 1000 mg/m² deux fois par jour pendant deux semaines, suivies d’une fenêtre thérapeutique de 7 jours.', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Xeloda®', 'draft', 103, '[{"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "500 mg"}]'::jsonb),
  ('capecitabine', 'capécitabine, comprimé 500 mg', 'En combinaison avec l’oxaliplatine et l’épirubicine', 'oxaliplatine', 'S. 625 mg/m² 2 fois par jour [dose en mg à calculer selon la surface corporelle]', '[["Dose initiale", "625 mg/m² 2x/j"]]'::jsonb, 'La dose recommandée de Xeloda est de 625 mg/m² deux fois par jour pendant 24 semaines sans interruption, en association avec 130 mg/m² d’ oxaliplatine (toutes les 3 semaines) et 50 mg/m² d’ épirubicine (toutes les 3 semaines).', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Xeloda®', 'draft', 104, '[{"form": "comprimé pelliculé", "dose": "150 mg"}, {"form": "comprimé pelliculé", "dose": "500 mg"}]'::jsonb),
  ('palbociclib', 'palbociclib, capsule 125 mg', null, null, 'S. 125 mg = 1 caps à prendre une fois par jour', '[["Dose initiale", "125 mg 1x/j"]]'::jsonb, 'La dose recommandée d''Ibrance est de 125 mg une fois par jour pendant 21 jours, suivie d''une pause de sept jours (schéma 3/1), constituant un cycle complet de 28 jours.', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Ibrance®', 'draft', 105, '[{"form": "comprimé pelliculé", "dose": "75 mg"}, {"form": "comprimé pelliculé", "dose": "100 mg"}, {"form": "comprimé pelliculé", "dose": "125 mg"}, {"form": "gélule", "dose": "75 mg"}, {"form": "gélule", "dose": "100 mg"}, {"form": "gélule", "dose": "125 mg"}]'::jsonb),
  ('ribociclib', 'ribociclib, comprimé 200 mg', 'Cancer du sein au stade précoce', 'sein;mammaire;precoce;adjuvant', 'S. 400 mg = 2 cp à prendre une fois par jour', '[["Dose initiale", "400 mg 1x/j"]]'::jsonb, 'Lorsque Kisqali est administré en association avec un inhibiteur de l''aromatase, la dose recommandée de Kisqali est de 400 mg (2 comprimés pelliculés de 200 mg) par voie orale une fois par jour pendant 21 jours consécutifs, suivis d''une interruption du traitement pendant 7 jours.', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Kisqali®', 'draft', 106, '[{"form": "comprimé pelliculé", "dose": "200 mg"}]'::jsonb),
  ('sunitinib', 'sunitinib, capsule 12,5 mg', 'Pancreatic NET', 'pancrea;neuroendocrine', 'S. 37,5 mg = 3 caps à prendre une fois par jour', '[["Dose initiale", "37,5 mg 1x/j"]]'::jsonb, 'La dose recommandée est de 37.5 mg une fois par jour sans pause (continuous daily dosing).', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Sutent®', 'draft', 107, '[{"form": "gélule", "dose": "12,5 mg"}, {"form": "gélule", "dose": "25 mg"}, {"form": "gélule", "dose": "50 mg"}]'::jsonb),
  ('talazoparib', 'talazoparib, capsule 0,5 mg', 'En association avec l''enzalutamide (cancer de la prostate)', 'prostat;enzalutamide', 'S. 0,5 mg = 1 caps à prendre une fois par jour', '[["Dose initiale", "0,5 mg 1x/j"]]'::jsonb, 'La dose recommandée de Talzenna est de 0.5 mg une fois par jour en association avec 160 mg d''enzalutamide une fois par jour par voie orale.', 'RCP Swissmedic (AIPS, 10.11.2026), extraction automatique, à vérifier : Talzenna®', 'draft', 108, '[{"form": "gélule", "dose": "0,1 mg"}, {"form": "gélule", "dose": "0,25 mg"}, {"form": "gélule", "dose": "0,35 mg"}, {"form": "gélule", "dose": "0,5 mg"}, {"form": "gélule", "dose": "1 mg"}]'::jsonb)
) as v(substance, product_line, indication, indication_match, sig, dose_levels, dose_note, source, status, position, strengths)
where not exists (select 1 from public.sl_rx e where e.substance = v.substance and e.product_line = v.product_line and split_part(e.sig, ' ', 2) = split_part(v.sig, ' ', 2))
on conflict (substance, product_line, (coalesce(indication, ''))) do nothing;
